contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 a, uint256 b) public {
        require(spender != address(0), "zero spender");
        require(a > 0 && b > 0, "amounts must be positive");
        // fund this contract with tokens via a mint from the deployer path:
        // fresh C has no balances; use burn to show conservation is trivially zero.
