        bool approved = c.approve(spender, a);
        uint256 beforeAllowance = c.allowance(address(this), spender);
        bool tooMuchReverted;
        try c.transferFrom(address(this), spender, a + b) { tooMuchReverted = false; }
        catch { tooMuchReverted = true; }
        uint256 midAllowance = c.allowance(address(this), spender);
        assert(approved && beforeAllowance == a && tooMuchReverted && midAllowance == a);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 b, uint256 a, uint256 extra) public {
        require(b > 0 && a > 0 && a <= b, "need 0 < a <= b");
        // set up: c was deployed by this test, so use transferFrom-based funding is impossible;
        // instead note that _mint is only reachable externally via mintSynth (needs curated pool).
        // However c's deployer path: this test is msg.sender == DEPLOYER, but there is no public mint.
        // Use the fact that a fresh C has zero balance: burning 0 is the only burn allowed;
        // so restrict to the observable rule: burning any a>0 with zero balance reverts and leaves state unchanged.
        require(a <= b, "unused");
        uint256 tsBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        bool reverted;
        try c.burn(a) { reverted = false; } catch { reverted = true; }
        uint256 tsAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        assert(reverted && tsAfter == tsBefore && balAfter == balBefore);
    }
    receive() external payable {}
}

