contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        // As the deployer/msg.sender of c, this contract's balance in c starts at 0;
        // but the rule must hold for whatever balance it has.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.transfer(address(0xdead), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // Must revert only because balance is insufficient
            assert(amount > balBefore);
            assert(c.balanceOf(address(this)) == balBefore);
        } else {
            // Success requires sufficient balance and moves exactly `amount`, leaving supply unchanged
            assert(amount <= balBefore);
            assert(c.balanceOf(address(this)) == balBefore - amount);
            assert(c.totalSupply() == supplyBefore);
        }
    }

    receive() external payable {}
}

