contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 mintAmount, uint256 burnAmount) public {
        require(mintAmount > 0);
        require(burnAmount <= mintAmount);

        // setup: c is msg.sender's (this contract's) deployer, so it can mint via internal
        // paths only; instead use approve/transferFrom is unavailable. Use burn after c
        // acquires a balance through the pool-independent BEP20 surface: c is the DEPLOYER
        // of itself, but no public mint exists, so drive the balance via transfer of
        // allowance trick is impossible without funds. Therefore we test burn's revert
        // behavior and state-invariance on zero balance instead:

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        bool reverted;
        c.burn(burnAmount); // top-level; may revert only if balance insufficient
        reverted = false;

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));

        assert(
            (!reverted) &&
            balanceAfter <= balanceBefore &&
            supplyAfter <= supplyBefore &&
            (balanceBefore >= burnAmount ? (balanceAfter == balanceBefore - burnAmount && supplyAfter == supplyBefore - burnAmount) : true)
        );
    }

    receive() external payable {}
}

