contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 approved, uint256 decrease) public {
        require(spender != address(0));

        bool firstReverted;
        try c.decreaseAllowance(spender, decrease) { firstReverted = false; }
        catch { firstReverted = true; }
        uint allowanceBefore = c.allowance(address(this), spender);

        c.approve(spender, approved);

        bool secondReverted;
        if (decrease <= approved) {
            bool ok = c.decreaseAllowance(spender, decrease);
            require(ok);
        } else {
            try c.decreaseAllowance(spender, decrease) { secondReverted = false; }
            catch { secondReverted = true; }
        }

        uint allowanceAfter = c.allowance(address(this), spender);

        if (decrease <= approved) {
            assert(!secondReverted && allowanceAfter == approved - decrease);
        } else {
            assert(secondReverted && firstReverted && allowanceBefore == 0 && allowanceAfter == approved);
        }
    }
}

