contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 initialAllowance, uint256 subtractedValue) public {
        require(spender != address(0));
        require(initialAllowance > 0);

        // Setup: grant an allowance to spender (top-level state-changing call)
        c.approve(spender, initialAllowance);

        uint256 before = c.allowance(address(this), spender);

        // Deciding call, recorded for revert
        bool reverted;
        try c.decreaseAllowance(spender, subtractedValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(address(this), spender);

        if (subtractedValue > before) {
            // Must revert and leave allowance untouched
            assert(reverted && afterAllowance == before);
        } else {
            // Must succeed and reduce allowance exactly by subtractedValue
            assert(!reverted && afterAllowance == before - subtractedValue);
        }
    }

    receive() external payable {}
}

