    function run(address spender, uint256 allowanceAmt, uint256 sub, uint256 add) public {
        require(spender != address(0));
        require(allowanceAmt > 0);

        c.approve(spender, allowanceAmt);
        assert(c.allowance(address(this), spender) == allowanceAmt);

        bool revertedSub;
        try c.decreaseAllowance(spender, sub) { revertedSub = false; } catch { revertedSub = true; }
        uint256 afterSub = c.allowance(address(this), spender);

        // restore full allowance before the increase check
        if (revertedSub) {
            c.approve(spender, allowanceAmt);
        }
        c.increaseAllowance(spender, add);
        uint256 afterAdd = c.allowance(address(this), spender);

        assert(
            (revertedSub == (sub > allowanceAmt))
            && (revertedSub ? (afterSub == allowanceAmt) : (afterSub == allowanceAmt - sub))
            && (afterAdd == (revertedSub ? allowanceAmt : allowanceAmt - sub) + add)
        );
    }

    receive() external payable {}
}

